<parameter=new_str>    def _get_callable(self, method):
        """Return the appropriate callable for the given HTTP method.

        If the module-level requests method is mocked (e.g., during unit tests),
        use it. Otherwise, use the session's method if available.
        """
        # Get the module-level function for this method
        module_func = getattr(requests, method)
        if hasattr(module_func, '_mock_call'):
            return module_func
        if self.session is not None:
            return getattr(self.session, method)
        return module_func

